// Get all fetched data
const tradeBacklog = $('Fetch TRADE Backlog').all().map(i => i.json);
const infraBacklog = $('Fetch INFRA Backlog').all().map(i => i.json);
const learnBacklog = $('Fetch LEARN Backlog').all().map(i => i.json);
const mgmtBacklog = $('Fetch MGMT Backlog').all().map(i => i.json);
const completed = $('Fetch Last Week Completed').all().map(i => i.json);
const tradingData = $('Fetch Trading Performance').first()?.json?.trades || [];

// Calculate velocity (story points completed last week)
const calculatePoints = (issues) => {
  return issues.reduce((sum, issue) => {
    const points = issue.fields?.customfield_storypoints || 
                   issue.fields?.customfield_10016 || 
                   1; // Default to 1 if no story points
    return sum + (typeof points === 'number' ? points : 1);
  }, 0);
};

const lastWeekVelocity = calculatePoints(completed);
const completedByProject = {
  TRADE: completed.filter(i => i.fields?.project?.key === 'TRADE'),
  INFRA: completed.filter(i => i.fields?.project?.key === 'INFRA'),
  LEARN: completed.filter(i => i.fields?.project?.key === 'LEARN'),
  MGMT: completed.filter(i => i.fields?.project?.key === 'MGMT')
};

// Format backlog items for proposal
const formatBacklogItem = (issue) => ({
  key: issue.key,
  summary: issue.fields?.summary?.substring(0, 80),
  priority: issue.fields?.priority?.name || 'Medium',
  type: issue.fields?.issuetype?.name || 'Task',
  storyPoints: issue.fields?.customfield_storypoints || issue.fields?.customfield_10016 || 1,
  created: issue.fields?.created,
  labels: issue.fields?.labels || []
});

// Prepare backlogs (top 5 per project)
const backlogs = {
  TRADE: tradeBacklog.slice(0, 5).map(formatBacklogItem),
  INFRA: infraBacklog.slice(0, 5).map(formatBacklogItem),
  LEARN: learnBacklog.slice(0, 5).map(formatBacklogItem),
  MGMT: mgmtBacklog.slice(0, 5).map(formatBacklogItem)
};

// Calculate backlog points
const backlogPoints = {
  TRADE: backlogs.TRADE.reduce((s, i) => s + i.storyPoints, 0),
  INFRA: backlogs.INFRA.reduce((s, i) => s + i.storyPoints, 0),
  LEARN: backlogs.LEARN.reduce((s, i) => s + i.storyPoints, 0),
  MGMT: backlogs.MGMT.reduce((s, i) => s + i.storyPoints, 0)
};

// Calculate trading performance summary
const weekPnL = tradingData.reduce((sum, t) => sum + (parseFloat(t.pnl) || 0), 0);
const winningTrades = tradingData.filter(t => parseFloat(t.pnl) > 0).length;
const winRate = tradingData.length > 0 ? (winningTrades / tradingData.length * 100) : 0;

// Suggest sprint capacity (80% of last week's velocity, minimum 5)
const suggestedCapacity = Math.max(Math.round(lastWeekVelocity * 0.8), 5);

// Generate sprint dates
const sprintStart = new Date();
const sprintEnd = new Date();
sprintEnd.setDate(sprintEnd.getDate() + 7);

return {
  json: {
    weekNumber: Math.ceil((new Date() - new Date(new Date().getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000)),
    sprintStart: sprintStart.toISOString().split('T')[0],
    sprintEnd: sprintEnd.toISOString().split('T')[0],

    velocity: {
      lastWeek: lastWeekVelocity,
      completedCount: completed.length,
      byProject: {
        TRADE: calculatePoints(completedByProject.TRADE),
        INFRA: calculatePoints(completedByProject.INFRA),
        LEARN: calculatePoints(completedByProject.LEARN),
        MGMT: calculatePoints(completedByProject.MGMT)
      }
    },

    suggestedCapacity,

    backlogs,
    backlogPoints,
    totalBacklogPoints: Object.values(backlogPoints).reduce((s, v) => s + v, 0),

    trading: {
      weekPnL: weekPnL.toFixed(2),
      tradeCount: tradingData.length,
      winRate: winRate.toFixed(1)
    },

    timestamp: new Date().toISOString()
  }
};

