const aiResponse = $json;
const velocityData = $('Calculate Velocity').first().json;

// Extract proposal text
const proposalText = aiResponse.content?.[0]?.text || 'Failed to generate proposal';

// Build Discord embed
const embed = {
  title: `:calendar: Sprint Planning - Week ${velocityData.weekNumber}`,
  description: proposalText.substring(0, 4000),
  color: 3447003, // Blue
  fields: [
    {
      name: ':chart_with_upwards_trend: Last Week Velocity',
      value: `${velocityData.velocity.lastWeek} points (${velocityData.velocity.completedCount} issues)`,
      inline: true
    },
    {
      name: ':dart: Suggested Capacity',
      value: `${velocityData.suggestedCapacity} points`,
      inline: true
    },
    {
      name: ':inbox_tray: Backlog Available',
      value: `${velocityData.totalBacklogPoints} points`,
      inline: true
    },
    {
      name: ':calendar: Sprint Dates',
      value: `${velocityData.sprintStart} to ${velocityData.sprintEnd}`,
      inline: false
    }
  ],
  footer: {
    text: 'React with :white_check_mark: to approve or :x: to reject'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    proposalText,
    velocityData,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing',
    waitTimeMinutes: 60 // Wait 1 hour for approval
  }
};

